#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <climits>
#include <tuple>
#include <functional>
using namespace std;

using i64 = long long;

struct Candidate {
    i64 a;
    i64 b;
};

inline pair<i64, i64> get_bounds(int x, int y, int b) {
    i64 num = static_cast<i64>(b) * x;
    i64 lo = num / y;
    i64 hi = (num + y - 1) / y;
    return {lo, hi};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y, n;
    cin >> x >> y >> n;

    vector<Candidate> pool;
    pool.reserve(2 * n);

    for (int b = 1; b <= n; ++b) {
        auto [lo, hi] = get_bounds(x, y, b);
        pool.push_back({lo, b});
        pool.push_back({hi, b});
    }

    auto error = [&](const Candidate& c) -> i64 {
        return llabs(static_cast<i64>(x) * c.b - c.a * y);
    };

    auto cmp = [&](const Candidate& lhs, const Candidate& rhs) {
        i64 el = error(lhs);
        i64 er = error(rhs);
        if (el != er) return el < er;
        if (lhs.b != rhs.b) return lhs.b < rhs.b;
        return lhs.a < rhs.a;
    };

    auto best = *min_element(pool.begin(), pool.end(), cmp);

    cout << best.a << "/" << best.b << '\n';

    return 0;
}
